Create a script to backfill embeddings for existing entities.

## File to Create
`packages/api/src/scripts/backfill-embeddings.ts`

## Implementation

```typescript
import "dotenv/config";
import { db, schema } from "../db/index.js";
import { eq, isNull, sql } from "drizzle-orm";
import {
  hasOpenAIClient,
  generateEmbeddingsBatch,
  prepareTextForEmbedding,
} from "../services/embedding.js";

// =============================================================================
// Configuration
// =============================================================================

const BATCH_SIZE = 50; // Items per batch
const DELAY_BETWEEN_BATCHES_MS = 500; // Rate limiting

// =============================================================================
// Table Configurations
// =============================================================================

const tables = [
  {
    name: "inbox_items",
    table: schema.inboxItems,
    type: "inbox_item" as const,
  },
  {
    name: "tasks",
    table: schema.tasks,
    type: "task" as const,
  },
  {
    name: "projects",
    table: schema.projects,
    type: "project" as const,
  },
  {
    name: "ideas",
    table: schema.ideas,
    type: "idea" as const,
  },
  {
    name: "persons",
    table: schema.persons,
    type: "person" as const,
  },
  {
    name: "personal_contexts",
    table: schema.personalContexts,
    type: "personal_context" as const,
  },
];

// =============================================================================
// Backfill Logic
// =============================================================================

async function backfillTable(config: (typeof tables)[0]): Promise<number> {
  const { name, table, type } = config;
  console.log(`\n📦 Backfilling ${name}...`);

  let totalProcessed = 0;
  let offset = 0;

  while (true) {
    // Fetch items without embeddings
    const items = await db
      .select()
      .from(table)
      .where(isNull(table.embedding))
      .limit(BATCH_SIZE)
      .offset(offset);

    if (items.length === 0) {
      console.log(`   ✓ ${name}: No more items to process`);
      break;
    }

    console.log(`   Processing batch of ${items.length} items (offset: ${offset})...`);

    // Prepare texts for embedding
    const texts = items.map((item) =>
      prepareTextForEmbedding({ type, data: item as Record<string, unknown> })
    );

    // Filter out empty texts
    const validIndices: number[] = [];
    const validTexts: string[] = [];
    texts.forEach((text, i) => {
      if (text.trim()) {
        validIndices.push(i);
        validTexts.push(text);
      }
    });

    if (validTexts.length === 0) {
      console.log(`   ⚠ Batch had no valid texts, skipping...`);
      offset += BATCH_SIZE;
      continue;
    }

    try {
      // Generate embeddings in batch
      const embeddings = await generateEmbeddingsBatch(validTexts);

      // Update each item with its embedding
      for (let i = 0; i < validIndices.length; i++) {
        const itemIndex = validIndices[i];
        const item = items[itemIndex];
        const embedding = embeddings[i];

        await db
          .update(table)
          .set({ embedding })
          .where(eq(table.id, (item as any).id));
      }

      totalProcessed += validTexts.length;
      console.log(`   ✓ Embedded ${validTexts.length} items`);
    } catch (error) {
      console.error(`   ✗ Batch failed:`, error);
      // Continue with next batch despite errors
    }

    offset += BATCH_SIZE;

    // Rate limiting delay
    await new Promise((resolve) => setTimeout(resolve, DELAY_BETWEEN_BATCHES_MS));
  }

  return totalProcessed;
}

async function getStats(): Promise<void> {
  console.log("\n📊 Current embedding status:");

  for (const { name, table } of tables) {
    const [total] = await db
      .select({ count: sql<number>\`count(*)\` })
      .from(table);

    const [withEmbedding] = await db
      .select({ count: sql<number>\`count(*)\` })
      .from(table)
      .where(sql\`embedding IS NOT NULL\`);

    const pct = total.count > 0 
      ? ((withEmbedding.count / total.count) * 100).toFixed(1)
      : "N/A";

    console.log(\`   ${name}: ${withEmbedding.count}/${total.count} (${pct}%)\`);
  }
}

// =============================================================================
// Main
// =============================================================================

async function main(): Promise<void> {
  console.log("🚀 Starting embedding backfill...\n");

  if (!hasOpenAIClient()) {
    console.error("❌ OPENAI_API_KEY not set. Cannot generate embeddings.");
    process.exit(1);
  }

  // Show current stats
  await getStats();

  // Backfill each table
  const results: Record<string, number> = {};
  for (const config of tables) {
    results[config.name] = await backfillTable(config);
  }

  // Summary
  console.log("\n" + "=".repeat(50));
  console.log("✅ Backfill complete!\n");

  for (const [name, count] of Object.entries(results)) {
    console.log(\`   ${name}: ${count} items embedded\`);
  }

  // Show final stats
  await getStats();

  process.exit(0);
}

main().catch((error) => {
  console.error("Fatal error:", error);
  process.exit(1);
});
```

