/**
 * Check if any embedded fields changed for an entity type.
 */
function hasEmbeddedFieldChange(
  entityType: "task" | "project" | "idea" | "person",
  updates: Record<string, unknown>
): boolean {
  const embeddedFields: Record<string, string[]> = {
    task: ["title", "nextAction", "context"],
