## Implementation

```typescript
import OpenAI from "openai";

// =============================================================================
// OpenAI Embedding Service
// =============================================================================

let openaiClient: OpenAI | null = null;

export function hasOpenAIClient(): boolean {
  return !!process.env.OPENAI_API_KEY;
}

export function getOpenAIClient(): OpenAI {
  if (!openaiClient) {
    if (!process.env.OPENAI_API_KEY) {
      throw new Error("OPENAI_API_KEY not configured");
    }
    openaiClient = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });
  }
  return openaiClient;
}

// =============================================================================
// Text Preparation
// =============================================================================

type EntityType = "inbox_item" | "task" | "project" | "idea" | "person" | "personal_context";

interface EntityData {
  type: EntityType;
  data: Record<string, unknown>;
}

/**
 * Prepare text for embedding by combining relevant fields per entity type.
 * Uses pipe separator to maintain some structure while keeping it readable.
 */
export function prepareTextForEmbedding(entity: EntityData): string {
  const { type, data } = entity;

  switch (type) {
    case "inbox_item":
      return String(data.rawText || "");

    case "task":
      return [
        data.title,
        data.nextAction,
        data.context,
      ].filter(Boolean).join(" | ");

    case "project":
      return [
        data.name,
        data.desiredOutcome,
        data.nextAction,
      ].filter(Boolean).join(" | ");

    case "idea":
      return [
        data.title,
        data.summary,
      ].filter(Boolean).join(" | ");

    case "person":
      return [
        data.name,
        data.relationshipContext,
        data.followUpNextAction,
      ].filter(Boolean).join(" | ");

    case "personal_context":
      return [
        data.name,
        data.description,
        data.domain,
      ].filter(Boolean).join(" | ");

    default:
      throw new Error(`Unknown entity type: ${type}`);
  }
}

// =============================================================================
// Embedding Generation
// =============================================================================

const EMBEDDING_MODEL = "text-embedding-3-small";
const EMBEDDING_DIMENSIONS = 1536;

/**
 * Generate embedding for a single text.
 */
export async function generateEmbedding(text: string): Promise<number[]> {
  if (!text.trim()) {
    throw new Error("Cannot embed empty text");
  }

  const client = getOpenAIClient();
  const response = await client.embeddings.create({
    model: EMBEDDING_MODEL,
    input: text,
    dimensions: EMBEDDING_DIMENSIONS,
  });

  return response.data[0].embedding;
}

/**
 * Generate embeddings for multiple texts in batch.
 * OpenAI supports up to 2048 inputs per request.
 */
export async function generateEmbeddingsBatch(texts: string[]): Promise<number[][]> {
  if (texts.length === 0) return [];

  const client = getOpenAIClient();
  const BATCH_SIZE = 100; // Conservative batch size
  const results: number[][] = [];

  for (let i = 0; i < texts.length; i += BATCH_SIZE) {
    const batch = texts.slice(i, i + BATCH_SIZE);
    const response = await client.embeddings.create({
      model: EMBEDDING_MODEL,
      input: batch,
      dimensions: EMBEDDING_DIMENSIONS,
    });

    // Ensure results are in the same order as inputs
    const sorted = response.data.sort((a, b) => a.index - b.index);
    results.push(...sorted.map(d => d.embedding));
  }

  return results;
}

/**
 * Convenience function to generate embedding for an entity.
 */
export async function generateEntityEmbedding(entity: EntityData): Promise<number[]> {
  const text = prepareTextForEmbedding(entity);
  return generateEmbedding(text);
}
