### 3. Add Reciprocal Rank Fusion (RRF) merge function

```typescript
/**
 * Merge keyword and semantic results using Reciprocal Rank Fusion.
 * RRF is robust to different score scales and performs well empirically.
 */
function mergeWithRRF<T extends { id: string }>(
  keywordResults: T[],
  semanticResults: Array<{ entity: T; similarity: number }>,
  semanticWeight: number
): T[] {
  const K = 60; // RRF constant (standard value)
  const scores = new Map<string, { score: number; item: T }>();

  // Score keyword results: (1 - weight) / (K + rank)
  keywordResults.forEach((item, index) => {
    const rrfScore = (1 - semanticWeight) / (K + index + 1);
    scores.set(item.id, { score: rrfScore, item });
  });

  // Score semantic results: weight / (K + rank)
  semanticResults.forEach(({ entity }, index) => {
    const rrfScore = semanticWeight / (K + index + 1);
    const existing = scores.get(entity.id);
    if (existing) {
      existing.score += rrfScore;
    } else {
      scores.set(entity.id, { score: rrfScore, item: entity });
    }
  });

  // Sort by combined score
  return Array.from(scores.values())
    .sort((a, b) => b.score - a.score)
    .map(({ item }) => item);
}
```

