      for (const { type, results } of similarResults) {
        for (const { entity, similarity } of results) {
          allSimilar.push({
            type,
            id: (entity as any).id,
            title: (entity as any).title || (entity as any).name,
            similarity,
          });
        }
      }

      // Sort by similarity and take top 5
